    // ══════════════════════════════════════════════════
    //  MODELS
    // ══════════════════════════════════════════════════
    class KhoiSoModel
    {
        public string TenKhoi { get; set; }
        public int SoLop { get; set; }
        public int SiSo { get; set; }
        public double TyLe { get; set; }
    }

    // ══════════════════════════════════════════════════
    //  STATE
    // ══════════════════════════════════════════════════
    private bool isLoading = false;
    private string maTruongBo = string.Empty;
    private string tenTruong = string.Empty;
    private DateTime lastUpdated = DateTime.Now;

    // Filters
    private string selectedCapHoc = "02";   // default Tiểu học
    private string selectedNamHoc = "2025-2026";
    private string selectedHocKy = "1";

    private static readonly Dictionary<string, string> capHocDict = new()
    {
        { "02", "Tiểu học" },
        { "03", "THCS" },
        { "04", "THPT" }
    };
    private List<KeyValuePair<string, string>> capHocList = new();
    private List<string> namHocList = new() { "2025-2026", "2024-2025", "2023-2024" };

    private bool isCapTieuHoc => selectedCapHoc == "02";

    // ── Dữ liệu ──
    private ThongKeThongTinTruongHoc? thongKeTruong;
    private ThongKeDiemDanh_DTO? tkDiemDanh;

    // PhuHuynh
    private int soPhHasAccount = 0;
    private int tongPhuHuynh = 0;
    private double zaloPercent = 0;

    // Điểm danh %
    private double attendancePercent = 0;

    // Tiểu học: T/H/C tổng hợp
    private int thData_T = 0, thData_H = 0, thData_C = 0;

    // THCS/THPT tổng hợp (dùng lớp "" để lấy toàn trường — gọi lớp đầu tiên)
    private DiemData.ThongKeTongKetHocTapDTO? thcsData;

    // Bảng khối sĩ số
    private List<KhoiSoModel> khoisoList = new();

    // Danh sách trường info
    private TruongHocData thData = new();

    // ══════════════════════════════════════════════════
    //  FILTER EVENTS
    // ══════════════════════════════════════════════════
    private async void OnCapHocChange(ChangeEventArgs e)
    {
        selectedCapHoc = e.Value?.ToString() ?? "02";
        await BrowserStorageService.SetItem(JS, "selectedLevel", selectedCapHoc);
        await LoadAllData();
    }

    private async void OnNamHocChange(ChangeEventArgs e)
    {
        selectedNamHoc = e.Value?.ToString() ?? selectedNamHoc;
        await BrowserStorageService.SetItem(JS, "selectedNamHoc", selectedNamHoc);
        await LoadAllData();
    }

    private async void OnHocKyChange(ChangeEventArgs e)
    {
        selectedHocKy = e.Value?.ToString() ?? "1";
        await BrowserStorageService.SetItem(JS, "selectedHocKy", selectedHocKy);
        await LoadAllData();
    }

    // ══════════════════════════════════════════════════
    //  HELPERS
    // ══════════════════════════════════════════════════
    private double GetSessionPercent(int? daDd, int? tong)
        => (tong.HasValue && tong > 0) ? Math.Round((double)daDd.GetValueOrDefault() * 100 / tong.Value, 1) : 0;

    private double GetPct(int val, int total)
        => total > 0 ? Math.Round((double)val * 100 / total, 1) : 0;

    private string GetCapHocText()
        => capHocDict.TryGetValue(selectedCapHoc, out var txt) ? txt : selectedCapHoc;

    // ══════════════════════════════════════════════════
    //  INIT
    // ══════════════════════════════════════════════════
    protected override async Task OnInitializedAsync()
    {
        // Đọc cấp học từ localStorage (cùng pattern với các trang điểm)
        try
        {
            var cap = await BrowserStorageService.GetItem(JS, "selectedLevel");
            if (!string.IsNullOrEmpty(cap)) selectedCapHoc = cap;

            var nh = await BrowserStorageService.GetItem(JS, "selectedNamHoc");
            if (!string.IsNullOrEmpty(nh)) selectedNamHoc = nh;

            var hk = await BrowserStorageService.GetItem(JS, "selectedHocKy");
            if (!string.IsNullOrEmpty(hk)) selectedHocKy = hk;
        }
        catch { /* mặc định đã set */ }

        // Build capHocList từ thông tin trường (sẽ lấy sau khi có maTruongBo)
        // Dùng dict mặc định trước
        capHocList = capHocDict.Select(kv => new KeyValuePair<string, string>(kv.Key, kv.Value)).ToList();

        maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);

        await LoadAllData();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!isLoading)
        {
            await RenderGradeChart();
        }
    }

    // ══════════════════════════════════════════════════
    //  LOAD DATA
    // ══════════════════════════════════════════════════
    private async Task LoadAllData()
    {
        if (string.IsNullOrEmpty(maTruongBo)) return;

        isLoading = true;
        StateHasChanged();

        try
        {
            // — Parallel load group 1: Thông tin trường + Phụ huynh —
            var taskTruong = TruongService.hGetThongKeTruong(maTruongBo, selectedCapHoc);
            var taskInfo   = TruongService.hThongTinTruongByID(maTruongBo);
            var taskPH     = TruongService.hGetThongTinPhuHuynh(maTruongBo);
            var taskKhoi   = TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc);
            var taskLop    = TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, selectedNamHoc);

            await Task.WhenAll( taskInfo, taskPH, taskKhoi, taskLop);

            // thongKeTruong = await taskTruong;
            var infoTruong = await taskInfo;
            tenTruong = infoTruong?.TenTruong ?? string.Empty;

            // Cập nhật capHocList từ thông tin trường nếu có
            if (infoTruong?.Cap != null && infoTruong.Cap.Length > 0)
            {
                capHocList = infoTruong.Cap
                    .Where(c => capHocDict.ContainsKey(c))
                    .Select(c => new KeyValuePair<string, string>(c, capHocDict[c]))
                    .ToList();
                if (!capHocList.Any(x => x.Key == selectedCapHoc))
                    selectedCapHoc = capHocList.FirstOrDefault().Key ?? "02";
            }

            // PH
            var phList = await taskPH;
            tongPhuHuynh = phList?.Count ?? 0;
            soPhHasAccount = phList?.Count(p => p.HasAccount == 1) ?? 0;
            zaloPercent = tongPhuHuynh > 0
                ? Math.Round((double)soPhHasAccount * 100 / tongPhuHuynh, 1) : 0;

            // Khối / Lớp
            thData.danhSachKhoiList = await taskKhoi;
            thData.danhSachLopList  = await taskLop;

            // — Điểm danh toàn trường hôm nay —
            try
            {
                tkDiemDanh = await DiemDanhServices.hGetThongKeDiemDanhTheoTruong(
                    maTruongBo, selectedCapHoc, selectedNamHoc, DateTime.Today, "");

                attendancePercent = (tkDiemDanh?.TongSoHocSinh ?? 0) > 0
                    ? Math.Round((double)(tkDiemDanh?.TongSoHocSinhDiemDanh ?? 0) * 100 / tkDiemDanh!.TongSoHocSinh, 1)
                    : 0;
            }
            catch { tkDiemDanh = null; }

            // — Bảng khối sĩ số —
            await BuildKhoiSoList();

            // — Xếp loại học lực —
            if (isCapTieuHoc)
                await LoadThData_C1();
            else
                await LoadThData_C2C3();

            lastUpdated = DateTime.Now;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi LoadAllData: {ex.Message}");
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    // ── Bảng khối: lấy sĩ số từng khối bằng cách đếm HS theo khối ──
    private async Task BuildKhoiSoList()
    {
        khoisoList.Clear();
        if (thData.danhSachKhoiList == null) return;

        foreach (var khoi in thData.danhSachKhoiList)
        {
            var lopCuaKhoi = thData.danhSachLopList?
                .Where(l => l.MaKhoiBo?.ToString() == khoi.MaKhoiBo?.ToString())
                .ToList() ?? new();

            int siSo = 0;
            foreach (var lop in lopCuaKhoi)
                siSo += await TruongService.hCountHocSinhByLop(lop.MaLopBo ?? "", selectedNamHoc, maTruongBo);

            // Tạm tính chuyên cần: nếu có tkDiemDanh toàn trường và chỉ 1 khối thì lấy tổng,
            // còn nhiều khối lấy tỷ lệ ước tính (thực tế cần gọi riêng từng khối)
            double tyLe = siSo > 0 ? attendancePercent : 0;

            khoisoList.Add(new KhoiSoModel
            {
                TenKhoi = khoi.TenKhoi ?? "",
                SoLop   = lopCuaKhoi.Count,
                SiSo    = siSo,
                TyLe    = tyLe
            });
        }
    }

    // ── Xếp loại Tiểu học: T/H/C — tổng hợp từ tất cả lớp ──
    private async Task LoadThData_C1()
    {
        thData_T = 0; thData_H = 0; thData_C = 0;
        if (thData.danhSachLopList == null) return;

        var hkInt = selectedHocKy == "1" ? 1 : 2;

        foreach (var lop in thData.danhSachLopList.Take(20)) // giới hạn 20 lớp để tránh quá nhiều query
        {
            try
            {
                var list = await TruongService.hGetThongKeDanhGiaTheoLop(lop.MaLopBo ?? "", selectedNamHoc);
                foreach (var item in list)
                {
                    if (hkInt == 1) { thData_T += item.T_HKI; thData_H += item.H_HKI; thData_C += item.C_HKI; }
                    else            { thData_T += item.T_CaNam; thData_H += item.H_CaNam; thData_C += item.C_CaNam; }
                }
            }
            catch { }
        }
    }

    // ── Xếp loại THCS/THPT: lấy từ lớp đầu tiên làm mẫu (dashboard tổng quan) ──
    private async Task LoadThData_C2C3()
    {
        thcsData = null;
        if (thData.danhSachLopList == null || !thData.danhSachLopList.Any()) return;

        // Domain: tổng hợp từ lớp đầu tiên (dashboard, không phải báo cáo chính xác)
        var firstLop = thData.danhSachLopList.FirstOrDefault();
        if (firstLop == null) return;
        try
        {
            thcsData = await DiemService.hThongKeKetQuaHocTap(
                maTruongBo, firstLop.MaLopBo ?? "", selectedNamHoc, selectedNamHoc);
        }
        catch { thcsData = null; }
    }

    // ── Render Chart.js ──
    private async Task RenderGradeChart()
    {
        try
        {
            if (isCapTieuHoc)
            {
                var labels = new[] { "Hoàn thành Tốt", "Hoàn thành", "Chưa hoàn thành" };
                var data   = new[] { thData_T, thData_H, thData_C };
                var colors = new[] { "#2563eb", "#f59e0b", "#ef4444" };
                await JS.InvokeVoidAsync("renderGradeChart", labels, data, colors);
            }
            else if (thcsData != null)
            {
                var labels = new[] { "Tốt", "Khá", "Đạt", "Chưa đạt" };
                var data   = new[] { thcsData.HK1_Tot, thcsData.HK1_Kha, thcsData.HK1_Dat, thcsData.HK1_ChuaDat };
                var colors = new[] { "#2563eb", "#10b981", "#f59e0b", "#ef4444" };
                await JS.InvokeVoidAsync("renderGradeChart", labels, data, colors);
            }
        }
        catch { }
    }

